import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"NumberInput","description":"","frontmatter":{},"headers":[],"relativePath":"components/number-input.md","filePath":"components/number-input.md"}'),r={name:"components/number-input.md"};function n(i,t,c,l,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="numberinput" tabindex="-1">NumberInput <a class="header-anchor" href="#numberinput" aria-label="Permalink to &quot;NumberInput&quot;">​</a></h1><p>NumberInput is the input of a number.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for an exact number, with its unit. It is empty when <code>value</code> is <code>null</code>; a <code>placeholder</code> can say what empty means (for example Auto). Only short values take a fixed width, one of 6, 8 or 12rem; without <code>width</code> it fills its container.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>null</code></td><td>The number, or <code>null</code> when empty (bindable)</td></tr><tr><td><code>unit</code></td><td></td><td>A unit on the right inside the control</td></tr><tr><td><code>min</code>, <code>max</code></td><td></td><td>The limits</td></tr><tr><td><code>step</code></td><td></td><td>The step; <code>any</code> takes decimals</td></tr><tr><td><code>placeholder</code></td><td></td><td>Shown while it is empty</td></tr><tr><td><code>width</code></td><td></td><td><code>6rem</code>, <code>8rem</code> or <code>12rem</code></td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name without a Field</td></tr><tr><td><code>id</code></td><td></td><td>The id of the input</td></tr><tr><td><code>error</code></td><td><code>false</code></td><td>The line turns red</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be focused or changed</td></tr><tr><td><code>readonly</code></td><td><code>false</code></td><td>Can be focused and selected, not changed</td></tr><tr><td><code>oninput</code></td><td></td><td>Every key stroke</td></tr><tr><td><code>onchange</code></td><td></td><td>The committed value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is the control of a <a href="./text-input">TextInput</a>. The number is aligned to the end, with figures of equal width, and the unit is muted on the right inside the control, trimmed to its ink.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/number-input/" title="NumberInput" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/number-input/" target="_blank" rel="noopener">NumberInput</a></figcaption></figure>',10)])])}const m=e(r,[["render",n]]);export{p as __pageData,m as default};
